/* Generated by tools/build.js from data/rhcsa.js. Edit that file, not this one. */
CertHub.addQuestions("rhcsa", [["rh1",0,1,"An admin runs a script and wants both normal output and error messages appended to /var/log/job.log without overwriting it. Which redirection is correct?",["job.sh > /var/log/job.log 2>&1","job.sh | tee /var/log/job.log","job.sh 2>&1 >> /var/log/job.log","job.sh >> /var/log/job.log 2>&1"],3,">> appends stdout, and 2>&1 afterwards sends stderr to the same place. Putting 2>&1 first copies stderr to the terminal before stdout moves; a single > overwrites the file.","Essential tools: I/O redirection"],["rh2",0,1,"Which command lists every line in /etc/passwd that ends with the string nologin?",["grep '^nologin' /etc/passwd","grep -v 'nologin' /etc/passwd","grep 'nologin$' /etc/passwd","grep -c 'nologin' /etc/passwd"],2,"$ anchors the match to the end of the line. ^ anchors to the start, -v inverts the match and -c only counts lines.","Essential tools: grep and regular expressions"],["rh3",0,1,"You need a compressed archive of /etc called /root/etc.tar.bz2. Which command creates it?",["tar -czf /root/etc.tar.bz2 /etc","tar -xjf /root/etc.tar.bz2 /etc","tar -cJf /root/etc.tar.bz2 /etc","tar -cjf /root/etc.tar.bz2 /etc"],3,"-c creates, -j uses bzip2 and -f names the file. -z would use gzip and -J xz, so the extension would be wrong; -x extracts.","Essential tools: archive and compress with tar and bzip2"],["rh4",0,1,"A user deletes /data/report.txt. A link that pointed to it still shows the old contents. What kind of link was it?",["An autofs map entry","A symbolic link to the path","A bind mount of the directory","A hard link to the same inode"],3,"A hard link is a second name for the same inode, so the data remains until the last hard link is removed. A symbolic link stores the path and would be broken.","Essential tools: hard and soft links"],["rh5",0,1,"Which command creates a symbolic link /usr/local/bin/backup that points to /opt/tools/backup.sh?",["ln /opt/tools/backup.sh /usr/local/bin/backup","cp -s /usr/local/bin/backup /opt/tools/backup.sh","ln -s /usr/local/bin/backup /opt/tools/backup.sh","ln -s /opt/tools/backup.sh /usr/local/bin/backup"],3,"ln -s TARGET LINKNAME: the existing file comes first and the new link name second. Without -s, ln makes a hard link.","Essential tools: hard and soft links"],["rh6",0,1,"A file must be readable and writable by its owner, readable by its group and give no access to others. Which numeric mode is correct?",["644","660","640","604"],2,"Owner rw = 6, group r = 4, others none = 0, giving 640. 644 would let others read the file.","Essential tools: list, set and change ugo/rwx permissions"],["rh7",0,1,"An admin wants to add execute permission for the group only on deploy.sh, without changing any other bits. Which command does this?",["chmod 710 deploy.sh","chmod g=x deploy.sh","chmod +x deploy.sh","chmod g+x deploy.sh"],3,"g+x adds execute for the group and leaves the rest alone. g=x would remove the group's read/write, +x adds execute for everyone, and 710 replaces every bit.","Essential tools: list, set and change ugo/rwx permissions"],["rh8",0,1,"You need to edit /etc/fstab but can't remember the meaning of its fields. Which command opens the documentation for the file format?",["whatis -f fstab","man 8 fstab","info mount -k","man 5 fstab"],3,"Section 5 of the manual covers file formats. Section 8 holds admin commands such as mount.","Essential tools: locate and use system documentation"],["rh9",0,1,"`man -k partition` returns 'nothing appropriate' on a fresh system. What should you run first?",["updatedb","restorecon -R /usr/share/man","dnf reinstall man","mandb"],3,"man -k searches the whatis database, which mandb builds. updatedb builds the locate database, not the man index.","Essential tools: locate and use system documentation"],["rh10",0,1,"You are logged in as a normal user and need a full root login environment with root's PATH and home directory. Which command is best?",["su root","sudo -s","su -","sudo su"],2,"su - (or su -l) starts a login shell as root, loading root's environment. Plain su keeps much of the current user's environment.","Essential tools: log in and switch users"],["rh11",0,1,"Which command copies the /srv/site directory tree to /backup while keeping permissions, ownership and timestamps?",["cp -i /srv/site /backup/","cp -r /srv/site /backup/","mv -f /srv/site /backup/","cp -a /srv/site /backup/"],3,"-a (archive) copies recursively and keeps modes, ownership, timestamps and links. -r copies recursively but not all attributes; mv moves the data instead of copying it.","Essential tools: create, delete, copy and move files"],["rh12",0,2,"A task says to use the repository at http://repo.example.com/BaseOS. Which line in the .repo file points dnf at it?",["mirrorlist=http://repo.example.com/BaseOS","url=http://repo.example.com/BaseOS","baseurl=http://repo.example.com/BaseOS","source=http://repo.example.com/BaseOS"],2,"baseurl= gives the location of the repository metadata. mirrorlist points to a list of mirrors, and url= and source= are not repo keys.","Manage software: configure access to RPM repositories"],["rh13",0,2,"The semanage command is missing on a minimal system. Which command tells you which package provides it?",["rpm -qf semanage","dnf provides '*/semanage'","dnf info semanage","rpm -ql semanage"],1,"dnf provides searches repository metadata for the package that owns a file. rpm -qf only works for files already installed.","Manage software: install and remove RPM packages"],["rh14",0,2,"Which command shows the configuration files that belong to the installed openssh-server package?",["rpm -qa openssh-server","rpm -qi openssh-server","dnf list openssh-server","rpm -qc openssh-server"],3,"-qc lists the package's config files. -qi shows package info, -qa lists installed packages and dnf list shows versions.","Manage software: install and remove RPM packages"],["rh15",0,2,"You must make Flathub available as a Flatpak source without an error if it already exists. Which command fits?",["flatpak install flathub --system","flatpak remote-add --if-not-exists flathub https://dl.flathub.org/repo/flathub.flatpakrepo","dnf config-manager --add-repo https://dl.flathub.org/repo/","flatpak remote-modify --enable flathub"],1,"flatpak remote-add creates a remote; --if-not-exists stops it from failing when the remote already exists. dnf config-manager adds RPM repos, not Flatpak remotes.","Manage software: configure access to Flatpak repositories"],["rh16",0,2,"Which command lists the Flatpak applications installed on the system?",["flatpak remotes","flatpak search --installed","flatpak list --app","dnf list installed flatpak"],2,"flatpak list shows installed refs, and --app filters out runtimes. flatpak remotes lists sources, and dnf only knows about RPMs.","Manage software: install and remove Flatpak packages"],["rh17",0,2,"A package update last week broke an application. Which approach reverts that transaction?",["dnf downgrade --all","rpm -e --nodeps on each package","dnf clean all then reboot","dnf history undo with the transaction ID"],3,"dnf history lists transactions and dnf history undo <ID> reverses one. dnf clean all only removes cached metadata.","Manage software: install and remove RPM packages"],["rh18",0,3,"In a script, which test is true when /etc/app.conf exists and is a regular file?",["[ -d /etc/app.conf ]","[ -z /etc/app.conf ]","[ -x /etc/app.conf ]","[ -f /etc/app.conf ]"],3,"-f tests for a regular file. -d is for directories, -z tests for an empty string and -x for execute permission.","Shell scripts: conditionally execute code"],["rh19",0,3,"A script must print a usage message when it is run with no arguments. Which condition detects that case?",["if [ $@ -eq 1 ]; then","if [ $0 -eq 0 ]; then","if [ $? -eq 0 ]; then","if [ $# -eq 0 ]; then"],3,"$# is the number of arguments. $0 is the script's name and $? the previous command's exit status.","Shell scripts: process script inputs"],["rh20",0,3,"Which loop runs a command once for every line in /root/hosts.txt, keeping spaces within each line?",["for h in /root/hosts.txt; do","while read -r h; do ... done < /root/hosts.txt","for h in $(ls /root/hosts.txt); do","until read h; do ... done > /root/hosts.txt"],1,"while read -r with input redirected from the file reads one full line at a time. The first for loop iterates once over the filename itself.","Shell scripts: use looping constructs"],["rh21",0,3,"Which line stores the number of lines containing 'bash' in /etc/passwd in the variable n?",["$n=$(grep -c bash /etc/passwd)","n='grep -c bash /etc/passwd'","n=grep -c bash /etc/passwd","n=$(grep -c bash /etc/passwd)"],3,"$( ) runs the command and substitutes its output. Single quotes store the literal text; $n= is not valid assignment syntax.","Shell scripts: process output of shell commands"],["rh22",0,3,"After running `grep -q root /etc/shadow`, a script checks `$?`. What does a value of 0 mean?",["The command was not found","The file could not be read","A match was found","No match was found"],2,"Exit status 0 means success, and for grep that means a match. grep returns 1 for no match and 2 for errors.","Shell scripts: conditionally execute code"],["rh23",0,3,"A script at /root/scripts/check.sh starts with #!/bin/bash but `./check.sh` returns 'Permission denied'. What is the fix?",["Add the directory to PATH","chmod +x /root/scripts/check.sh","Change the shebang to #!/bin/sh","Run restorecon on the script"],1,"Running a script by path needs execute permission. PATH only matters when you type the name without a path.","Shell scripts: create simple shell scripts"],["rh24",0,4,"You need to reset a lost root password on RHEL 10. At the GRUB menu, what do you add to the kernel line?",["single","init=/sbin/nologin","systemd.unit=multi-user.target","rd.break"],3,"rd.break stops boot in the initramfs, where you remount /sysroot read-write, chroot and run passwd. multi-user.target is a normal boot.","Operate running systems: interrupt the boot process to gain access"],["rh25",0,4,"After changing the root password from the rd.break shell, why do you run `touch /.autorelabel` before rebooting?",["It forces fsck on the root file system","It makes SELinux relabel files, fixing /etc/shadow's context","It rebuilds the initramfs for the new password","It clears the systemd journal"],1,"passwd in the chroot creates /etc/shadow with the wrong SELinux label. The autorelabel flag makes SELinux relabel the file system on the next boot so logins work.","Operate running systems: interrupt the boot process to gain access"],["rh26",0,4,"A server is slow. Which command lists processes sorted by CPU use, highest first?",["ps aux --sort=-%cpu","ps -ef --sort=pid","pgrep -l cpu","top -b -n 1 -o PID | head"],0,"ps aux --sort=-%cpu sorts by CPU descending (the minus sign reverses the order). Sorting by pid doesn't show the heavy processes first.","Operate running systems: identify CPU and memory intensive processes"],["rh27",0,4,"A process with PID 4120 ignores `kill 4120`. Which command ends it without giving it a chance to clean up?",["kill -1 4120","kill -15 4120","kill -9 4120","kill -18 4120"],2,"Signal 9 (SIGKILL) cannot be caught or ignored. 15 is SIGTERM, which is what plain kill already sent; 1 is SIGHUP and 18 is SIGCONT.","Operate running systems: kill processes"],["rh28",0,4,"A backup job with PID 2250 should use less CPU than other processes. Which command gives it the lowest scheduling priority?",["renice -n -20 -p 2250","nice -n 19 2250","renice -n 19 -p 2250","kill -STOP 2250"],2,"A nice value of 19 is the lowest priority, and renice changes a running process. -20 is the highest priority; nice only starts new commands.","Operate running systems: adjust process scheduling"],["rh29",0,4,"Which command applies the tuning profile that tuned suggests for the current system?",["tuned-adm profile $(tuned-adm recommend)","tuned-adm active","systemctl set-default tuned","tuned-adm profile --recommended --apply-now"],0,"tuned-adm recommend prints the suggested profile, and tuned-adm profile applies it. tuned-adm active only shows the current profile.","Operate running systems: manage tuning profiles"],["rh30",0,4,"After a reboot, `journalctl -b -1` says there are no earlier boots. What change makes journal entries survive reboots?",["Set Storage=persistent in journald.conf and restart systemd-journald","Enable the rsyslog service","Set SystemMaxUse=0 in journald.conf","Run logrotate -f /etc/logrotate.conf"],0,"By default the journal lives in /run and is lost at reboot unless /var/log/journal exists. Storage=persistent creates and uses it. rsyslog writes text logs but does not keep the journal.","Operate running systems: preserve system journals"],["rh31",0,4,"Which command shows only error-level and more severe messages logged by the sshd service since this morning at 08:00?",["journalctl -p err -u sshd --since 08:00","journalctl -f -u sshd --until 08:00","journalctl -k -p err --since 08:00","grep err /var/log/sshd --since 08:00"],0,"-p err filters by priority, -u selects the unit and --since limits the time. -k shows only kernel messages; there is no /var/log/sshd by default.","Operate running systems: locate and interpret system log files and journals"],["rh32",0,4,"Failed su and ssh login attempts on RHEL are written to which text log file by default?",["/var/log/messages","/var/log/audit/audit.log","/var/log/boot.log","/var/log/secure"],3,"rsyslog writes authentication and authorization messages (authpriv) to /var/log/secure. /var/log/messages holds general messages.","Operate running systems: locate and interpret system log files"],["rh33",0,4,"You must copy /etc/hosts to /tmp on server2 over an encrypted connection. Which command works?",["scp /etc/hosts server2:/tmp/","cp /etc/hosts server2:/tmp/","ssh server2 cp /etc/hosts /tmp/","sftp /etc/hosts server2:/tmp/"],0,"scp copies files over SSH. The ssh command would copy server2's own /etc/hosts, and sftp takes a host, not a source file, as its argument.","Operate running systems: securely transfer files between systems"],["rh34",0,4,"A system won't finish booting because of a bad fstab entry. Which kernel argument boots to a minimal root shell with the root file system mounted read-only?",["systemd.unit=graphical.target","systemd.unit=emergency.target","systemd.unit=multi-user.target","systemd.unit=default.target"],1,"emergency.target gives a root shell with / mounted read-only and few services. The others try to start the full system and hit the same fstab error.","Operate running systems: boot systems into different targets manually"],["rh35",0,5,"A new blank disk /dev/vdb needs a GPT partition table. Which command creates one?",["parted /dev/vdb mklabel gpt","mkfs.gpt /dev/vdb","fdisk -t gpt /dev/vdb1","pvcreate --gpt /dev/vdb"],0,"parted mklabel gpt writes a new GPT partition table. mkfs.gpt doesn't exist, and pvcreate prepares LVM physical volumes.","Configure local storage: list, create and delete partitions on GPT disks"],["rh36",0,5,"You created /dev/vdb1 for LVM. Which command must come before vgcreate can use it?",["lvcreate /dev/vdb1","mkfs.xfs /dev/vdb1","pvcreate /dev/vdb1","vgextend /dev/vdb1"],2,"pvcreate writes the LVM physical volume header. vgextend adds a PV to an existing VG, and mkfs would put a file system on it.","Configure local storage: create and remove physical volumes"],["rh37",0,5,"A task asks for volume group vgapp with a physical extent size of 16 MiB on /dev/vdb1. Which command is right?",["vgcreate -l 16M vgapp /dev/vdb1","vgcreate -s 16M vgapp /dev/vdb1","vgcreate vgapp /dev/vdb1 -L 16M","vgcreate --extents 16 vgapp /dev/vdb1"],1,"-s sets the physical extent size when the VG is created. -l and -L are lvcreate options for extents and size.","Configure local storage: assign physical volumes to volume groups"],["rh38",0,5,"Volume group vgapp has 16 MiB extents. A task asks for logical volume lvlog made of exactly 40 extents. Which command creates it?",["lvcreate -L 40 -n lvlog vgapp","lvcreate -L 640M lvlog vgapp","lvcreate -s 40 -n lvlog vgapp","lvcreate -l 40 -n lvlog vgapp"],3,"-l takes a count of extents. -L 40 would mean 40 MiB, and -s creates a snapshot.","Configure local storage: create and delete logical volumes"],["rh39",0,5,"Which /etc/fstab entry mounts an XFS file system by UUID on /data at boot?",["UUID=4f1c...e2 /data xfs defaults 0 0","/data UUID=4f1c...e2 xfs defaults 0 0","UUID=4f1c...e2 xfs /data defaults 0 0","UUID=4f1c...e2 /data defaults xfs 0 0"],0,"The field order is device, mount point, type, options, dump, fsck. The other entries put fields in the wrong order.","Configure local storage: mount file systems at boot by UUID or label"],["rh40",0,5,"Which command shows the UUID and file system type of /dev/vdb1?",["pvs /dev/vdb1","df -T /dev/vdb1","fdisk -u /dev/vdb1","blkid /dev/vdb1"],3,"blkid reads the UUID, label and type from the device. df only works on mounted file systems and doesn't show UUIDs.","Configure local storage: mount file systems at boot by UUID or label"],["rh41",0,5,"You created a new swap partition /dev/vdb2 and added it to fstab. Which commands prepare and activate it?",["mkfs.swap /dev/vdb2; mount -a","swapon /dev/vdb2; mkswap -a","mkswap /dev/vdb2; swapon -a","mkswap -a; swapon /dev/vdb2 -p"],2,"mkswap writes the swap signature, then swapon -a activates every swap entry in fstab. Swap is not mounted with mount.","Configure local storage: add swap non-destructively"],["rh42",0,5,"Which fstab line makes a swap partition persistent?",["UUID=9ab2...77 /swap swap defaults 0 0","UUID=9ab2...77 none swap defaults 0 0","UUID=9ab2...77 swap none defaults 0 0","UUID=9ab2...77 none swap defaults 0 2"],1,"Swap uses none (or swap) as the mount point field, swap as the type, and 0 for fsck. A mount point like /swap, a swapped field order or an fsck pass of 2 are wrong.","Configure local storage: add swap non-destructively"],["rh43",0,5,"A disk already has two partitions holding data. You must add a third partition without disturbing them. What is the safest approach?",["Run parted mklabel gpt and recreate all three","Use mkpart in the free space, then run partprobe or udevadm settle","Run wipefs on the disk and repartition","Delete partition 2 and resize it to fit the new one"],1,"Creating a partition only in unused space leaves the existing ones untouched; partprobe makes the kernel see it. mklabel and wipefs destroy the existing table.","Configure local storage: add new partitions non-destructively"],["rh44",0,5,"Which command shows all block devices, their sizes and mount points as a tree, including LVM volumes?",["lsblk","pvdisplay","mount -l","fdisk -s"],0,"lsblk shows disks, partitions and the LVs on them with sizes and mount points. pvdisplay only shows physical volumes.","Configure local storage: list partitions"],["rh45",0,5,"An unused logical volume /dev/vgapp/lvold must be removed. Which command does it?",["vgreduce vgapp lvold","lvreduce -L 0 /dev/vgapp/lvold","pvremove /dev/vgapp/lvold","lvremove /dev/vgapp/lvold"],3,"lvremove deletes a logical volume (unmount it and remove its fstab entry first). vgreduce removes a PV from a VG and pvremove wipes a PV label.","Configure local storage: create and delete logical volumes"],["rh46",0,6,"A USB stick image must use a file system that Windows can also read. Which command creates it on /dev/vdc1?",["mkfs.xfs /dev/vdc1","mkfs.ext4 /dev/vdc1","mkfs.vfat /dev/vdc1","mkswap /dev/vdc1"],2,"vfat (FAT32) is readable by Windows, macOS and Linux. XFS and ext4 are Linux file systems.","File systems: create, mount and use vfat, ext4 and xfs"],["rh47",0,6,"The XFS logical volume /dev/vgdata/lvweb is mounted and needs 500 MiB more space. Which single command grows the LV and its file system?",["lvextend -r -L +500M /dev/vgdata/lvweb","lvresize -L 500M /dev/vgdata/lvweb","xfs_growfs -L +500M /dev/vgdata/lvweb","resize2fs /dev/vgdata/lvweb 500M"],0,"-r resizes the file system after extending the LV. -L 500M (no +) sets an absolute size, which could shrink it; resize2fs is for ext4.","File systems: extend existing logical volumes"],["rh48",0,6,"You need to make an XFS file system smaller. What is true?",["xfs_growfs can shrink it if it is unmounted","XFS cannot be shrunk; back up, recreate and restore","lvreduce -r shrinks XFS safely online","xfs_repair -L shrinks it to the LV size"],1,"XFS can only grow. To make it smaller you must back up the data, create a smaller file system and restore. ext4 can shrink when unmounted.","File systems: extend existing logical volumes"],["rh49",0,6,"Which fstab entry mounts the NFS export nfs1:/exports/share on /mnt/share at boot, waiting for the network first?",["nfs1:/exports/share /mnt/share xfs defaults 0 0","/mnt/share nfs1:/exports/share nfs defaults 0 0","nfs1:/exports/share /mnt/share nfs defaults,_netdev 0 0","nfs1:/exports/share /mnt/share nfs defaults 0 1"],2,"The type is nfs, _netdev marks it as needing the network, and network file systems get 0 for fsck. The other lines have the wrong type, field order or fsck value.","File systems: mount and unmount network file systems using NFS"],["rh50",0,6,"You need home directories from nfs1:/home/<user> to mount on demand under /rhome/<user>. In /etc/auto.master.d/rhome.autofs you point /rhome at /etc/auto.rhome. What goes in /etc/auto.rhome?",["* -rw,sync nfs1:/home/&","& -rw,sync nfs1:/home/*","/rhome/* nfs1:/home/* nfs rw","* nfs1:/home -rw,sync"],0,"In an indirect map, * matches any key accessed under /rhome and & repeats that key in the server path. The options come between the key and the location.","File systems: configure autofs"],["rh51",0,6,"You edited autofs map files but /rhome/alice still doesn't mount. autofs is running. What should you do next?",["Run mount -a","Run exportfs -r on the client","Restart autofs with systemctl","Add the path to /etc/fstab"],2,"autofs reads the master map at start, so restart or reload it after changes. mount -a only uses fstab, and exportfs runs on the NFS server.","File systems: configure autofs"],["rh52",0,6,"A user can't read /projects/team/plan.txt even though the file is mode 644. What is the most likely cause?",["The file needs the sticky bit","The user's umask is too strict","A parent directory lacks execute permission for the user","The file is not owned by root"],2,"To reach a file a user needs execute (search) permission on every directory in the path; namei -l shows where it fails. umask only affects new files.","File systems: diagnose and correct file permission problems"],["rh53",0,6,"After adding a line to /etc/fstab, how do you test it without rebooting?",["Run mount -a and check with findmnt","Run systemctl isolate local-fs.target now","Run partprobe then reboot","Run fsck -A on every disk"],0,"mount -a mounts every fstab entry that isn't already mounted, so errors appear now instead of at boot. findmnt --verify also checks the file.","File systems: mount and unmount file systems"],["rh54",0,6,"Which command formats /dev/vgdata/lvdocs with ext4 and the label DOCS?",["mkfs.ext4 -n DOCS /dev/vgdata/lvdocs","mkfs.ext4 -L DOCS /dev/vgdata/lvdocs","mkfs.xfs -L DOCS /dev/vgdata/lvdocs","e2label -c DOCS /dev/vgdata/lvdocs"],1,"mkfs.ext4 -L sets the label, which fstab can use as LABEL=DOCS. mkfs.xfs would create the wrong type.","File systems: create ext4 file systems"],["rh55",0,7,"A cleanup script must run at 02:30 every day through cron. Which crontab line is correct?",["2 30 * * * /usr/local/bin/cleanup.sh","30 2 * * * /usr/local/bin/cleanup.sh","30 2 1 * * /usr/local/bin/cleanup.sh","* 2 30 * * /usr/local/bin/cleanup.sh"],1,"Cron fields are minute, hour, day of month, month, day of week. 30 2 * * * is 02:30 daily; the third option runs only on the 1st.","Deploy and maintain: schedule tasks using cron"],["rh56",0,7,"You wrote report.service and report.timer with OnCalendar=Mon *-*-* 06:00:00. What makes the job run on schedule, including after reboots?",["systemctl enable --now report.service","systemctl start report.service","systemctl enable --now report.timer","crontab -e and add report.timer"],2,"The timer unit triggers the service, so enable and start the timer. Enabling the service would just run it at boot.","Deploy and maintain: schedule tasks using systemd timers"],["rh57",0,7,"Which command runs /root/fix.sh once, 20 minutes from now?",["echo /root/fix.sh | at now + 20 minutes","at -f /root/fix.sh daily","crontab -e 20m /root/fix.sh","systemd-run --on-calendar=+20"],0,"at runs a job once at a given time, reading commands from stdin. The cron-style options run on a repeating schedule or use invalid syntax.","Deploy and maintain: schedule tasks using at"],["rh58",0,7,"httpd must start now and also start at every boot. Which command does both?",["systemctl start httpd --boot","systemctl unmask httpd","systemctl enable httpd","systemctl enable --now httpd"],3,"enable --now creates the boot-time symlinks and starts the service. enable alone only takes effect at the next boot.","Deploy and maintain: start and stop services and configure them to start at boot"],["rh59",0,7,"A graphical server should boot to a text console by default. Which command sets this?",["systemctl isolate multi-user.target","systemctl set-default multi-user.target","systemctl enable rescue.target","grubby --set-default multi-user"],1,"set-default changes the default target used at boot. isolate switches targets now but doesn't change the default.","Deploy and maintain: configure systems to boot into a specific target"],["rh60",0,7,"A server must get its time from classroom.example.com. Which line in /etc/chrony.conf does this?",["ntpserver classroom.example.com prefer","server classroom.example.com iburst","pool = classroom.example.com","timeserver classroom.example.com"],1,"chrony uses server (or pool) followed by a host name; iburst speeds up the first sync. Restart chronyd and check with chronyc sources.","Deploy and maintain: configure time service clients"],["rh61",0,7,"Which command adds the kernel argument audit=1 to every installed kernel's boot entry?",["grubby --update-kernel=ALL --args=\"audit=1\"","grub2-install --args=\"audit=1\"","dracut --add audit=1 --all","sysctl -w audit=1"],0,"grubby edits the boot entries directly. grub2-install installs the boot loader and dracut builds the initramfs.","Deploy and maintain: modify the system bootloader"],["rh62",0,7,"You edited GRUB_TIMEOUT in /etc/default/grub on a BIOS system. What makes the change take effect?",["dracut -f","grub2-mkconfig -o /boot/grub2/grub.cfg","systemctl restart grub2","grubby --info=ALL"],1,"grub2-mkconfig regenerates grub.cfg from /etc/default/grub and the scripts in /etc/grub.d. grubby --info only displays entries.","Deploy and maintain: modify the system bootloader"],["rh63",0,7,"A new RHEL 10 VM from the Developer subscription can't reach the Red Hat CDN repositories. What should you do first?",["Run subscription-manager register","Run dnf clean all","Enable EPEL","Set gpgcheck=0 and sslverify=0 in /etc/dnf/dnf.conf"],0,"The CDN repositories only work on a registered system; register with subscription-manager and your Red Hat account. Cleaning caches doesn't grant access.","Deploy and maintain: install and update packages from Red Hat CDN"],["rh64",0,8,"Connection 'ens3' must use 10.0.0.20/24, gateway 10.0.0.1 and no DHCP. Which command sets this?",["nmcli con mod ens3 ipv4.addresses 10.0.0.20/24 ipv4.gateway 10.0.0.1 ipv4.method manual","nmcli dev set ens3 ip 10.0.0.20/24 gw 10.0.0.1","ip addr add 10.0.0.20/24 dev ens3 permanent","nmcli con mod ens3 ipv4.method auto ipv4.addresses 10.0.0.20/24"],0,"nmcli con mod changes the saved profile; ipv4.method manual turns off DHCP. ip addr add is lost at reboot, and method auto keeps DHCP.","Manage basic networking: configure IPv4 and IPv6 addresses"],["rh65",0,8,"You changed the IP settings of connection 'ens3' with nmcli con mod. How do you apply them now?",["systemctl restart network","nmcli general reload dns","ifup ens3 --reload","nmcli con up ens3"],3,"Reactivating the connection applies the changed profile. The legacy network service and ifup scripts are not part of RHEL 10.","Manage basic networking: configure IPv4 and IPv6 addresses"],["rh66",0,8,"Where does RHEL 10 store persistent NetworkManager connection profiles?",["/etc/sysconfig/network-scripts/ifcfg-*","/etc/network/interfaces","/etc/NetworkManager/system-connections/","/run/NetworkManager/devices/"],2,"RHEL 10 uses keyfiles (*.nmconnection) in /etc/NetworkManager/system-connections/. ifcfg files are no longer supported, and /etc/network/interfaces is a Debian file.","Manage basic networking: configure network settings"],["rh67",0,8,"Which command sets the persistent hostname to web1.example.com?",["hostname web1.example.com","echo web1.example.com >> /etc/sysconfig/network","nmcli con mod hostname web1.example.com","hostnamectl set-hostname web1.example.com"],3,"hostnamectl set-hostname writes /etc/hostname and applies the name immediately. The hostname command alone is lost at reboot.","Manage basic networking: configure hostname resolution"],["rh68",0,8,"Connection 'ens3' needs DNS server 10.0.0.53. Which method survives NetworkManager restarts?",["Edit /etc/resolv.conf directly","nmcli con mod ens3 ipv4.dns 10.0.0.53","Add 10.0.0.53 to /etc/hosts","hostnamectl set-dns 10.0.0.53"],1,"NetworkManager writes /etc/resolv.conf from the connection's ipv4.dns setting, so manual edits are overwritten. /etc/hosts maps names, not DNS servers.","Manage basic networking: configure hostname resolution"],["rh69",0,8,"The web server must be reachable on the http service after reboots. Which pair of commands is correct?",["firewall-cmd --add-service=http; firewall-cmd --runtime-to-reboot","firewall-cmd --permanent --add-port=http; systemctl restart httpd","firewall-cmd --permanent --add-service=http; firewall-cmd --reload","firewall-cmd --add-service=http --zone=trusted --save"],2,"--permanent saves the rule and --reload loads it into the running firewall. Without --permanent the rule is lost at reload or reboot.","Manage basic networking: restrict network access using firewall-cmd"],["rh70",0,8,"Which command shows which TCP ports are listening and which processes own them?",["ss -tlnp","ip route show","nmcli dev status","ping -c1 localhost"],0,"ss -tlnp lists TCP listening sockets with numeric ports and process names. ip route shows routes, not sockets.","Manage basic networking: configure network services to start at boot"],["rh71",0,9,"Create user svcbackup with UID 1500 and no interactive login. Which command does this?",["useradd -u 1500 -s /sbin/nologin svcbackup","useradd -g 1500 -s /bin/false svcbackup","usermod -u 1500 -L svcbackup","useradd -U 1500 -d /dev/null svcbackup"],0,"-u sets the UID and -s /sbin/nologin blocks interactive logins. -g sets the primary group, and usermod changes an existing user.","Users and groups: create, delete and modify local user accounts"],["rh72",0,9,"User alice must be added to group developers without losing her other supplementary groups. Which command is right?",["usermod -G developers alice","useradd -G developers alice","groupmod -a alice developers","usermod -aG developers alice"],3,"-a with -G appends. -G alone replaces all supplementary groups, and useradd creates new users.","Users and groups: modify group membership"],["rh73",0,9,"Which command makes user bob choose a new password the next time he logs in?",["chage -d 0 bob","chage -M 0 bob","passwd -l bob","usermod -e 0 bob"],0,"Setting the last change date to 0 forces a change at next login. -M 0 sets a zero-day maximum age, and passwd -l locks the account.","Users and groups: change passwords and adjust password aging"],["rh74",0,9,"New accounts must default to a 60-day maximum password age. Which file should you edit?",["/etc/default/useradd","/etc/security/pwquality.conf","/etc/login.defs","/etc/shadow"],2,"PASS_MAX_DAYS in /etc/login.defs sets the default for new accounts. Editing /etc/shadow changes existing users only, and pwquality controls password complexity.","Users and groups: change passwords and adjust password aging"],["rh75",0,9,"Create group finance with GID 4000. Which command is correct?",["groupadd -u 4000 finance","groupmod -g 4000 finance","addgroup finance 4000","groupadd -g 4000 finance"],3,"groupadd -g sets the GID when creating a group. groupmod changes an existing group, and addgroup is not a RHEL command.","Users and groups: create, delete and modify local groups"],["rh76",0,9,"Members of group admins must run any command as root through sudo. Which drop-in line is correct?",["admins ALL=(ALL) ALL","%admins ALL=(ALL) ALL","@admins ALL=(ALL) ALL","group:admins ALL=ALL"],1,"In sudoers a % prefix marks a group. Without it, sudo treats admins as a user name.","Users and groups: configure superuser access"],["rh77",0,9,"Which command removes user olduser along with the home directory and mail spool?",["userdel -f olduser","usermod -L olduser","userdel -r olduser","deluser --home olduser"],2,"userdel -r deletes the account, home directory and mail spool. -f forces removal even while logged in, and usermod -L only locks the account.","Users and groups: create, delete and modify local user accounts"],["rh78",0,10,"httpd must serve files from /srv/web with SELinux enforcing. Which commands set the right context in a way that survives a relabel?",["chcon -R -t httpd_sys_content_t /srv/web","setsebool -P httpd_read_srv on","semanage fcontext -a -t httpd_sys_content_t \"/srv/web(/.*)?\"; restorecon -Rv /srv/web","chmod -R 755 /srv/web; restorecon -Rv /srv/web"],2,"semanage fcontext adds a lasting rule and restorecon applies it. chcon changes labels only until the next relabel or restorecon.","Manage security: restore default file contexts"],["rh79",0,10,"Which command shows the SELinux context of files in /var/www/html?",["ls -Z /var/www/html","getsebool /var/www/html","sestatus /var/www/html","id -Z /var/www/html"],0,"ls -Z adds the SELinux context to the listing. id -Z shows your own context and sestatus the overall SELinux state.","Manage security: list and identify SELinux file and process context"],["rh80",0,10,"httpd is set to listen on TCP 8090 but fails to start with SELinux enforcing. Which command fixes the SELinux side?",["setsebool -P httpd_can_network_connect on","semanage port -a -t http_port_t -p tcp 8090","firewall-cmd --permanent --add-port=8090/tcp","restorecon -Rv /etc/httpd"],1,"The port needs the http_port_t label before httpd_t may bind to it. The boolean controls outgoing connections, and the firewall rule affects clients, not whether httpd starts.","Manage security: manage SELinux port labels"],["rh81",0,10,"Web apps need to connect to a remote database. Which command allows this permanently?",["setsebool -P httpd_can_network_connect_db on","setsebool httpd_can_network_connect_db on","semanage port -a -t db_port_t 3306","setenforce 0"],0,"setsebool -P saves the boolean so it survives reboots. Without -P it resets at boot, and setenforce 0 disables protection for everything.","Manage security: use boolean settings to modify SELinux settings"],["rh82",0,10,"Which command searches the audit log for recent SELinux denials?",["journalctl -u selinux","ausearch -m AVC -ts recent","getenforce -v","grep -i avc /var/log/secure /var/log/boot.log"],1,"SELinux denials are AVC records in /var/log/audit/audit.log, and ausearch -m AVC filters them. They don't appear in /var/log/secure.","Manage security: diagnose and address routine SELinux policy violations"],["rh83",0,10,"SELinux must stay enforcing after reboot. It is currently permissive. What do you do?",["setenforce 1 only","Set SELINUX=enforcing in /etc/selinux/config and run setenforce 1","Set SELINUXTYPE=enforcing and reboot","Run semanage enforce -P on"],1,"setenforce changes the mode now; /etc/selinux/config sets the mode at boot. SELINUXTYPE picks the policy (targeted), not the mode.","Manage security: set enforcing and permissive modes for SELinux"],["rh84",0,10,"While troubleshooting you want SELinux to log denials but not block anything, only until the next reboot. Which command fits?",["setenforce 0","setsebool -P permissive on","getenforce 0","semanage permissive -a all"],0,"setenforce 0 switches to permissive mode until reboot. The others use invalid options or change settings permanently.","Manage security: set enforcing and permissive modes for SELinux"],["rh85",0,10,"A user's umask is 0027. What permissions does a new directory they create get?",["rwxr-xr-x (755)","rw-r----- (640)","rwxr-x--- (750)","rwxrwx--- (770)"],2,"Directories start from 777; removing 027 leaves 750. New files start from 666 and would be 640.","Manage security: manage default file permissions"],["rh86",0,10,"User deploy needs password-free SSH to server2. After running ssh-keygen, which command installs the public key on server2?",["scp ~/.ssh/id_ed25519 server2:~/.ssh/","ssh-copy-id deploy@server2","ssh-add deploy@server2","ssh-keyscan server2 >> ~/.ssh/authorized_keys"],1,"ssh-copy-id appends your public key to ~/.ssh/authorized_keys on the remote host and fixes permissions. Copying the private key is unsafe, and ssh-keyscan collects host keys.","Manage security: configure key-based authentication for SSH"],["rh87",0,10,"Key login fails and the sshd log mentions bad ownership or modes for authorized_keys. Which permissions should you set?",["~/.ssh 755 and authorized_keys 644","~/.ssh 777 and authorized_keys 666","~/.ssh 700 and authorized_keys 600","~/.ssh 711 and authorized_keys 755"],2,"With StrictModes on, sshd refuses keys if others can write to ~/.ssh or authorized_keys. 700 and 600 owned by the user are the safe values.","Manage security: configure key-based authentication for SSH"],["rh88",0,10,"After allowing key logins, the admin wants to block password logins over SSH. Which sshd_config setting does this?",["PubkeyAuthentication no","PermitRootLogin prohibit-password","UsePAM no","PasswordAuthentication no"],3,"PasswordAuthentication no disables password logins for all users; then reload sshd. prohibit-password only affects root.","Manage security: configure key-based authentication for SSH"],["rh89",0,10,"Only hosts in 192.168.50.0/24 should reach services in the internal zone. Which command sends that network's traffic to the internal zone permanently?",["firewall-cmd --permanent --zone=internal --add-source=192.168.50.0/24","firewall-cmd --permanent --zone=internal --add-interface=192.168.50.0/24","firewall-cmd --zone=internal --add-port=192.168.50.0/24","firewall-cmd --set-default-zone=192.168.50.0/24"],0,"--add-source binds a network to a zone, so its traffic uses that zone's rules. --add-interface takes an interface name, not a network, and default-zone takes a zone name.","Manage security: configure firewall settings using firewall-cmd"],["rh90",0,10,"Which command shows the SELinux context of the running httpd processes?",["ls -Z /usr/sbin/httpd","ps -eZ | grep httpd","getsebool -a | grep httpd","seinfo -p httpd"],1,"ps -eZ adds the process context, such as httpd_t. ls -Z shows the executable file's label, not the process.","Manage security: list and identify SELinux process context"]]);
